import React, { useEffect, useRef } from "react";
import "./App.css";
import { Link } from "react-router-dom";
import ShinyText from "./ShinyText";
import SplitText from "./SplitText";
import CircularGallery from "./CircularGallery";

function About() {
  const sectionsRef = useRef([]);
  const bgVideoRef = useRef(null);
  const handleAnimationComplete = () => {
    console.log('All letters have animated!');
  };

  useEffect(() => {
    // Scroll to top smoothly when About section is mounted
    window.scrollTo({ top: 0, behavior: "smooth" });
  } , []);
   
  useEffect(() => {
    const loadScript = (src) =>
      new Promise((resolve) => {
        const script = document.createElement("script");
        script.src = src;
        script.onload = resolve;
        document.head.appendChild(script);
      });

    Promise.all([
      loadScript("https://cdnjs.cloudflare.com/ajax/libs/animejs/3.2.1/anime.min.js"),
    ]).then(() => {
      const anime = window.anime;

      const observer = new IntersectionObserver(
        (entries, obs) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              anime({
                targets: entry.target.querySelector(".content-container"),
                opacity: [0, 1],
                translateY: [50, 0],
                duration: 1000,
                easing: "easeOutExpo",
              });
              obs.unobserve(entry.target);
            }
          });
        },
        { threshold: 0.3 }
      );

      sectionsRef.current.forEach((section) => {
        if (section) observer.observe(section);
      });
    });
  }, []);

  useEffect(() => {
    const cards = document.querySelectorAll(".glass-card");

    cards.forEach((card) => {
      const specular = card.querySelector(".glass-specular");

      const handleMove = (e) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (specular) {
          specular.style.background = `radial-gradient(
            circle at ${x}px ${y}px,
            rgba(255,255,255,0.2) 0%,
            rgba(255,255,255,0.05) 10%,
            rgba(255,255,255,0) 20%
          )`;
        }
      };

      const handleLeave = () => {
        if (specular) {
          specular.style.background = "none";
        }
      };

      const handleclick = (e) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (!specular) return;

        let progress = 0;   // from 0 to 1
        const duration = 700; // animation duration in ms
        const startTime = performance.now();

        function animate(time) {
          progress = (time - startTime) / duration;
          if (progress > 1) progress = 1;

          // Calculate gradient radius in % (start small, grow bigger)
          // Let's say radius grows from 10% to 100%
          const radius1 = 1 + 99 * progress;  // inner stop
          const radius2 = radius1 + 10;        // second stop a bit further

          // Calculate opacity fading out from 0.2 to 0
          const opacity = 0.2 * (1 - progress);

          specular.style.background = `radial-gradient(
            circle at ${x}px ${y}px,
            rgba(255,255,255,${opacity}) 0%,
            rgba(255,255,255,${opacity * 0.25}) ${radius1}%,
            rgba(255,255,255,0) ${radius2}%
          )`;

          if (progress < 1) {
            requestAnimationFrame(animate);
          } else {
            // Clear background after animation ends
            specular.style.background = "";
          }
        }

        requestAnimationFrame(animate);
      };


      card.addEventListener("mousemove", handleMove);
      card.addEventListener("mouseleave", handleLeave);
      card.addEventListener("click", handleclick);

      return () => {
        card.removeEventListener("mousemove", handleMove);
        card.removeEventListener("mouseleave", handleLeave);
      };
    });
  }, []);

  useEffect(() => {
    const nav = document.querySelector('.sticky-nav');
    const menuToggle = document.querySelector('.sticky-nav-toggle');
    const menu = document.querySelector('.sticky-nav-menu');
    const navLinks = document.querySelectorAll('.sticky-nav-menu a');
    const sections = document.querySelectorAll('section');

    // Handle nav background shadow on scroll
    const onScroll = () => {
      if (window.scrollY > 50) {
        nav.classList.add('scrolled');
      } else {
        nav.classList.remove('scrolled');
      }

      // Scroll spy active link update
      let currentSectionId = "";
      sections.forEach(section => {
        const sectionTop = section.offsetTop - 80; // adjust offset to nav height
        if (window.scrollY >= sectionTop) {
          currentSectionId = section.getAttribute('id');
        }
      });

      navLinks.forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === `#${currentSectionId}`) {
          link.classList.add('active');
        }
      });
    };

    // Toggle mobile menu open/close
    const toggleMenu = () => {
      menu.classList.toggle('mobile-active');
      const icon = menuToggle.querySelector('i');
      if (icon.classList.contains('fa-bars')) {
        icon.classList.remove('fa-bars');
        icon.classList.add('fa-times');
      } else {
        icon.classList.remove('fa-times');
        icon.classList.add('fa-bars');
      }
    };

    // Close mobile menu on link click (scroll spy updates active link)
    const onNavLinkClick = () => {
      if (window.innerWidth <= 768) {
        menu.classList.remove('mobile-active');
        const icon = menuToggle.querySelector('i');
        icon.classList.remove('fa-times');
        icon.classList.add('fa-bars');
      }
    };

    window.addEventListener('scroll', onScroll);
    menuToggle?.addEventListener('click', toggleMenu);
    navLinks.forEach(link => {
      link.addEventListener('click', onNavLinkClick);
    });

    // Reset mobile menu if window resized above breakpoint
    const onResize = () => {
      if (window.innerWidth > 768) {
        menu.classList.remove('mobile-active');
        const icon = menuToggle.querySelector('i');
        if (icon.classList.contains('fa-times')) {
          icon.classList.remove('fa-times');
          icon.classList.add('fa-bars');
        }
      }
    };
    window.addEventListener('resize', onResize);

    // Set initial state
    onScroll();

    return () => {
      window.removeEventListener('scroll', onScroll);
      menuToggle?.removeEventListener('click', toggleMenu);
      navLinks.forEach(link => {
        link.removeEventListener('click', onNavLinkClick);
      });
      window.removeEventListener('resize', onResize);
    };
  }, []);

/* add an intrests with the circular gallery */

  const sections = [
    {
      id: "about-intro",
      title: "About Me",
      content: `I'm Jaynil, a high school student passionate about exploring the fields of aerospace ,AI, and software engineering. 
        I thrive on hands-on innovation, whether it's programming facial recognition systems or simulating rocket trajectories. 
        This page offers a deeper dive into my background, goals, and motivations.`,
    },
    {
      id: "skills",
      title: "My Skills",
      content: [
        "Intermediate Python Coder",
        "Beginner React Developer",
        "Beginner Godot Developer",
        "Intermediate Machine Learning Knowledge",
        "Beginner C++ Developer",
        "Beginner OpenFOAM User",
      ],
    },
    {
      id: "goals",
      title: "My Goals",
      content: `My goal for my career is to study Aerospace Engineering in university and contribute to space exploration through technological innovation.`,
    },
    {
      id: "intrests",
      title: "My Intrests",
    },
    {
      id: "achievments",
      title: "Achievments",
      content: [
        "2nd Placee in Incubator Hacks II",
        "#1st Place in the Turner Fenton Hackathon",
        "Bronze Cross Certification",
        "Intermediate Machine Learning"
      ],
    },
  ];

  useEffect(() => {
    const loadScript = (src) =>
      new Promise((resolve) => {
        const script = document.createElement("script");
        script.src = src;
        script.onload = resolve;
        document.head.appendChild(script);
      });

    loadScript("https://kit.fontawesome.com/a076d05399.js");
  }, []);

  return (
    <>
      <video
        id="bg-video"
        ref={bgVideoRef}
        muted
        autoPlay
        loop        
        playsInline
        src="blackhole.mp4"
      />

      <nav className="sticky-nav">
        <div className="sticky-nav-logo">
          <img
            src="/JP_Logo.png"
            alt="Logo"
            style={{
              width: "80px",
              height: "80px",
              objectFit: "cover",
              alignContent: "center",
            }}
          />
          <Link to="/" className="active">
            <ShinyText text="Jaynil Patel" disabled={false} speed={3} className="custom-class" />
          </Link>
        </div>

        <button className="sticky-nav-toggle" aria-label="Toggle menu">
          <i className="fas fa-bars"></i>
        </button>

        <ul className="sticky-nav-menu">
          <li><a href="#about-intro" className="active">About Me</a></li>
          <li><a href="#skills">My Skills</a></li>
          <li><a href="#goals">My Goals</a></li>
          <li><a href="#achievments">My Achievments</a></li>
        </ul>
      </nav>

      {sections.map(({ id, title, content, link, hasButton, buttonText }, i) => (
        <section
          key={id}
          id={id}
          className="anime-section"
          ref={(el) => (sectionsRef.current[i] = el)}
        >
          <div className="section-inner auto-size">
            <div className="glass-card">
              <div className="glass-filter" />
              <div className="glass-distortion-overlay" />
              <div className="glass-overlay" />
              <div className="glass-specular" />
            </div>

            <div className="content-container">
              <h2>{title}</h2>

              {Array.isArray(content) ? (
                <div className="skills-grid">
                  {content.map((skill, index) => (
                    <div className="glass-card mini-card" key={index}>
                      <div className="glass-filter" />
                      <div className="glass-distortion-overlay" />
                      <div className="glass-overlay" />
                      <div className="glass-specular" />
                      <div className="content-container">
                        <p>{skill}</p>
                      </div>
                    </div>
                  ))}
                </div>
                ) : (
                  id === "about-intro" ? (
                    <p>{content}</p>
                ) : id === "intrests" ? (
                  <div style={{ height: '600px', width: '600px', position: 'relative' }}>
                    <CircularGallery bend={3} textColor="#ffffff" borderRadius={0.05} />
                  </div>        
                ) : (
                    <p>{content}</p>
                  )
                )}


              {hasButton && link && buttonText && (
                <Link to={link}>
                  <button className="glass-button">{buttonText}</button>
                </Link>
              )}
            </div>
          </div>
        </section>
      ))}
    </>
  );
}

export default About;
